        )
    )
}

@Composable
fun PrivacyRulesScreen(modifier: Modifier = Modifier) {
    TextPageScreen(
        modifier = modifier,
        title = "Правила и приватност",
        paragraphs = listOf(
            "**Издавач:** Александар Милошевић",
            "**Ел. пошта:** milosevicaleksandar1998@gmail.com",
            "Мали пречник је бесплатан речник без огласа и без аналитике. Основна претрага, сопствено складиште, увоз и извоз раде на самом (личном) уређају.",
            "Спонишни (онлајн) део постоји само за предлоге и гласање. За то се користе Firebase Anonymous Auth и Cloud Firestore. Firebase додељује технички скривени id, без имена, лозинке, ел. поште или налога.",
            "Предлози корисника не постају одмах јавно видљиви. Прво се шаљу на уреднички преглед. Тек одобрени предлози могу бити приказани на страници **Гласање**.",
            "У предлоге није дозвољено уносити увредљив, незаконит, претећи, неприкладан, обмањујући или туђ лични садржај. Не уносити личне податке, бројеве телефона, адресе, ел. поште, лозинке или осетљиве податке.",
            "Корисник може за себе да запречи (блокира) предлагача чије предлоге не жели да види. Запречивање важи само на том уређају. Корисник може и да пријави појединачан предлог и његовог предлагача уреднику као неприкладне, након чега тај предлог може бити уклоњен.",
            "Подаци послати као предлог, глас или пријава чувају се ради уредничког прегледа, спречавања злоупотребе и припреме будућих издања јавног складишта речи. За питања о приватности, безбедности или брисању података треба писати на наведену ел. пошту."
        )
    )
}

@Composable
private fun TextPageScreen(
    modifier: Modifier = Modifier,
    title: String,
    paragraphs: List<String>,
    footer: (@Composable ColumnScope.() -> Unit)? = null
) {
    LazyColumn(
        modifier = modifier.padding(horizontal = 16.dp, vertical = 14.dp),
        verticalArrangement = Arrangement.spacedBy(14.dp)
    ) {
        item {
            Surface(
                modifier = Modifier.fillMaxWidth(),
                shape = RoundedCornerShape(8.dp),
                color = MaterialTheme.colorScheme.surface
            ) {
                Column(
                    modifier = Modifier.padding(14.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    Text(
                        text = title,
                        style = MaterialTheme.typography.titleLarge,
                        fontWeight = FontWeight.SemiBold
                    )
                    paragraphs.forEach { paragraph ->
                        Text(
                            text = formattedAnnotatedString(paragraph),
                            style = MaterialTheme.typography.bodyLarge
                        )
                    }
                    footer?.invoke(this)
                }
            }
        }
    }
}
